CREATE POLICY "Anyone can read resume files" ON storage.objects FOR SELECT USING (bucket_id = 'resume');
CREATE POLICY "Admins can upload resume files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'resume' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can update resume files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'resume' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can delete resume files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'resume' AND public.has_role(auth.uid(), 'admin'));